        except (OverflowError, ValueError) as exc:
            raise FloatingPointError(
                "non-finite value encountered during mean squared error"
            ) from exc
        if (
            not math.isfinite(d)
            or not math.isfinite(q)
            or not math.isfinite(u)
        ):
            raise FloatingPointError(
                "non-finite value encountered during mean squared error"
            )
