        try:
            total = math.fsum(terms)
        except (OverflowError, ValueError) as exc:
            raise FloatingPointError(
                "non-finite value encountered during concordance "
                "correlation coefficient"
            ) from exc
        if not math.isfinite(total):
            raise FloatingPointError(
                "non-finite value encountered during concordance "
                "correlation coefficient"
            )
